# robust parse summaries: malformed tasks, bad dates, hours anomalies, task bonus mismatches by type
import csv, re, ast, collections, datetime as dt, calendar
with open('/app/dataset/tasks.csv', newline='') as f: tasks=list(csv.DictReader(f))
pay={int(t['task_id']):int(t['pay_per_completion']) for t in tasks}
valid_ids=set(pay)
with open('/app/dataset/timesheet.csv', newline='') as f: rows=list(csv.DictReader(f))

def parse_ints(s): return [int(x) for x in re.findall(r'\d+', s)]
print('Malformed performed_tasks rows:')
for r in rows:
    try: ast.literal_eval(r['performed_tasks'])
    except Exception as e:
        ints=parse_ints(r['performed_tasks'])
        print(r['id'], r['date'], r['employee_id'], r['performed_tasks'], 'ints', ints, 'known_sum', sum(pay.get(x,0) for x in ints), 'bonus', r['bonus'], 'salary', r['salary_amount'])
print('\nNon-numeric / negative / zero hours counts')
ctr=collections.Counter(r['hours_worked'] for r in rows)
print(sorted(ctr.items(), key=lambda x:float(x[0]) if x[0].lstrip('-').isdigit() else 999))
print('zero rows')
for r in rows:
    if float(r['hours_worked'])<=0:
        print(r)
# unknown task ids in parse_ints and possible correction by bonus residual
unknowns=[]
for r in rows:
    ints=parse_ints(r['performed_tasks'])
    miss=[x for x in ints if x not in valid_ids]
    if miss:
        known=sum(pay.get(x,0) for x in ints)
        residual=float(r['bonus'])-known
        unknowns.append((r['id'],r['performed_tasks'],miss,known,float(r['bonus']),residual))
print('\nrows with unknown task id',len(unknowns))
for item in unknowns[:120]: print(item)
