from __future__ import annotations

import csv
import datetime as dt
import json
import re
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP


EMPLOYEES_PATH = "/app/dataset/employees.csv"
TASKS_PATH = "/app/dataset/tasks.csv"
TIMESHEET_PATH = "/app/dataset/timesheet.csv"
OUTPUT_PATH = "/app/answer.json"


def _read_csv(path: str) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def _parse_date(value: str) -> dt.date | None:
    try:
        return dt.date.fromisoformat(value)
    except ValueError:
        return None


def _first_weekday_in_month(year: int, month: int, weekday: int) -> dt.date:
    first = dt.date(year, month, 1)
    return first + dt.timedelta(days=(weekday - first.weekday()) % 7)


def _previous_month(year: int, month: int) -> tuple[int, int]:
    if month == 1:
        return year - 1, 12
    return year, month - 1


def _billing_period_start(date: dt.date, billing_weekday: int) -> dt.date:
    start = _first_weekday_in_month(date.year, date.month, billing_weekday)
    if date >= start:
        return start

    prev_year, prev_month = _previous_month(date.year, date.month)
    return _first_weekday_in_month(prev_year, prev_month, billing_weekday)


def _round_salary(value: Decimal) -> int:
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def answer() -> dict[str, list[int]]:
    employees = _read_csv(EMPLOYEES_PATH)
    tasks = _read_csv(TASKS_PATH)
    timesheet = _read_csv(TIMESHEET_PATH)

    hourly_rates = {
        employee["PESEL"]: Decimal(employee["hourly_rate"])
        for employee in employees
    }
    task_pay = {
        int(task["task_id"]): Decimal(task["pay_per_completion"])
        for task in tasks
    }

    valid_dates = [
        parsed
        for row in timesheet
        if (parsed := _parse_date(row["date"])) is not None
    ]
    if not valid_dates:
        return {}

    billing_weekday = min(valid_dates).weekday()
    totals: dict[str, dict[dt.date, Decimal]] = defaultdict(lambda: defaultdict(Decimal))
    seen_rows: set[tuple[tuple[str, str], ...]] = set()

    for row in timesheet:
        work_date = _parse_date(row["date"])
        if work_date is None:
            continue

        pesel = row["employee_id"]
        hourly_rate = hourly_rates.get(pesel)
        if hourly_rate is None:
            continue

        dedupe_key = tuple((key, row[key]) for key in sorted(row) if key != "id")
        if dedupe_key in seen_rows:
            continue
        seen_rows.add(dedupe_key)

        task_ids = [int(value) for value in re.findall(r"\d+", row["performed_tasks"])]
        bonus = sum((task_pay[task_id] for task_id in task_ids if task_id in task_pay), Decimal(0))
        base_pay = Decimal(row["hours_worked"]) * hourly_rate
        period_start = _billing_period_start(work_date, billing_weekday)
        totals[pesel][period_start] += base_pay + bonus

    result: dict[str, list[int]] = {}
    for employee in employees:
        pesel = employee["PESEL"]
        if pesel not in totals:
            continue
        result[pesel] = [
            _round_salary(total)
            for _, total in sorted(totals[pesel].items())
        ]

    return result


if __name__ == "__main__":
    with open(OUTPUT_PATH, "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
